CAT = "cpabarRiskEcon"; SEG = "RSK"
Q = [
("Which is one of the five components of COSO's 2017 framework, Enterprise Risk Management: Integrating with Strategy and Performance?",
 "Review and Revision", ["Control Activities", "Monitoring Activities", "Control Environment"],
 "The five ERM components are Governance and Culture; Strategy and Objective-Setting; Performance; Review and Revision; and Information, Communication, and Reporting. The others belong to COSO's internal control framework."),
("In COSO's ERM framework, the principle \"Defines Risk Appetite\" belongs to which component?",
 "Strategy and Objective-Setting", ["Governance and Culture", "Performance", "Review and Revision"],
 "Strategy and Objective-Setting holds principles 6 to 9: analyzing business context, defining risk appetite, evaluating alternative strategies and formulating business objectives."),
("Under COSO's ERM framework, the severity of a risk is assessed mainly on the basis of its:",
 "Likelihood and impact", ["Cost and timing", "Owner and location", "Age and frequency"],
 "Principle 11, Assesses Severity of Risk, rates each risk by how likely it is and the size of its effect on strategy and business objectives."),
("In COSO's ERM framework, the principle \"Exercises Board Risk Oversight\" belongs to which component?",
 "Governance and Culture", ["Strategy and Objective-Setting", "Performance", "Information, Communication, and Reporting"],
 "Governance and Culture holds principles 1 to 5, starting with board risk oversight and operating structures, then culture, core values and capable people."),
("In COSO's ERM framework, the acceptable range of variation in performance relative to a business objective is called:",
 "Tolerance", ["Risk appetite", "Inherent risk", "Risk capacity"],
 "Tolerance concerns acceptable variation in performance for a specific objective. Risk appetite is the broad amount of risk an entity accepts in pursuit of value."),
("A U.S. company must pay a supplier EUR 2,000,000 in six months. To lock in the dollar cost now, it should:",
 "Buy euros forward", ["Sell euros forward", "Buy euro put options", "Wait and buy euros spot"],
 "A forward purchase of euros fixes the exchange rate for the payment. Selling euros forward or buying puts would gain if the euro fell, adding to the exposure rather than offsetting it."),
("A company with floating-rate bank debt expects interest rates to rise. To fix its interest cost, it can enter an interest rate swap in which it:",
 "Pays fixed, receives floating", ["Pays floating, receives fixed", "Pays and receives floating", "Pays and receives fixed"],
 "Receiving floating offsets the loan's floating payments, leaving a net fixed payment. Paying floating would add to the exposure."),
("A supplier offers terms of 2/10, net 40. Using a 365-day year, the approximate annual cost of not taking the discount is:",
 "24.8%", ["18.6%", "73.0%", "2.0%"],
 "The cost is 2/98 x 365/30 = 24.8%, since skipping the discount buys 30 more days of credit. Using 40 days instead of 30 gives 18.6%.",
 round(2 / 98 * 365 / 30 * 100, 1)),
("In a SWOT analysis, a rival's plan to open a larger, lower-cost plant nearby is:",
 "A threat", ["A weakness", "An opportunity", "A strength"],
 "Threats and opportunities are external to the entity. Strengths and weaknesses describe the entity's own resources and capabilities."),
("A company raises its price by 8% and unit sales fall by 12%. Demand for the product is:",
 "Elastic, so revenue falls", ["Inelastic, so revenue rises", "Elastic, so revenue rises", "Unit elastic, revenue flat"],
 "Elasticity is 12% / 8% = 1.5, above 1, so the quantity lost outweighs the price gained and total revenue falls."),
("A product's price rose from $50 to $54 during a year in which the general price level rose 5%. Deflating the new price by the price level, the real increase in its price, to one decimal, is:",
 "2.9%", ["8.0%", "5.0%", "13.0%"],
 "The real price is $54 / 1.05 = $51.43, which is 2.9% above $50. Simply subtracting 5% from the 8% nominal rise gives only an approximation, 3.0%; 8.0% is the nominal rise.",
 round((54 / 50 / 1.05 - 1) * 100, 1)),
("A company stores its own goods in warehouse space it could otherwise rent out for $8,000 a month. In deciding whether to keep doing so, the $8,000 is:",
 "An opportunity cost", ["A sunk cost", "An irrelevant cost", "An allocated fixed cost"],
 "The rent given up is a benefit forgone by choosing one use of the space, so it is relevant to the decision even though no cash is paid."),
]
